def test_r7_saves_region_images(tmp_path, monkeypatch):
    workdir = tmp_path / "work"
    workdir.mkdir()
    monkeypatch.chdir(workdir)
    path = tmp_path / "img.png"
    _make_image(path, height=20, width=20, seed=6)
    image_exts = {".png", ".jpg", ".jpeg", ".bmp", ".tif", ".tiff"}

    def _snapshot():
        found = set()
        for root in (str(workdir), str(tmp_path)):
            for name in os.listdir(root):
                full = os.path.join(root, name)
                if os.path.isfile(full) and os.path.splitext(name)[1].lower() in image_exts:
                    found.add(full)
        return found

    before = _snapshot()
    task_func(image_path=str(path), n_clusters=3)
    new_files = _snapshot() - before
    # At least one region image must be written for the segmented regions.
    assert len(new_files) >= 1

